// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address actor, address account) public {
        vm.assume(actor != address(0));
        bool ok;
        vm.prank(actor);
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }
        // A caller can only renounce a role for itself; renouncing for any
        // other account must revert.
        assertTrue(ok == (account == actor));
    }
}
